import { Routes } from '@angular/router';
import { provideRouter } from '@angular/router';
import {AboutPageComponent} from './pages/about-page/about-page.component';

export const routes: Routes = [
  { path: '', redirectTo: 'vote', pathMatch: 'full' },
  { path: 'about', component: AboutPageComponent},
  { path: 'vote',
    loadComponent: () => import('./pages/game-vote-page/game-vote-page.component').then(m => m.GameVotePageComponent),
    title: 'Wählen'
  },
  { path: 'search',
    loadComponent: () => import('./pages/game-list-page/game-list-page.component').then(m => m.GameListPageComponent),
    title: 'Spiele suchen'
  },
  {
    path: 'game/:id',
    loadComponent: () => import('./pages/game-detail-page/game-detail-page.component').then(m => m.GameDetailPageComponent)
  }
];

export const routingProviders = [
  provideRouter(routes)
];
