import {Injectable} from '@angular/core';
import { HttpClient } from '@angular/common/http';
import {BehaviorSubject, map, Observable} from 'rxjs';
import {Club} from '../models/club.model';
import {Season} from '../models/season.model';
import {Game} from '../models/game.model';
import {GamePlayerStat} from '../models/gameplayerstats.model';
import {Venue} from '../models/venue.model';

@Injectable({ providedIn: 'root' })
export class TvzApiService {
  private baseUrl = 'https://api.tvzofingen.ch/rest/v2';
  private clubsCache: Club[] = [];
  private venuesCache: Venue[] = [];
  private seasonSubject = new BehaviorSubject<number | null>(null);
  readonly season$ = this.seasonSubject.asObservable();

  constructor(private http: HttpClient) {
    this.loadFromStorage();
    this.getSeasons().subscribe(seasons => {
      const storedId = this.getSeasonId();
      const actual = seasons.find(s => s.isActual);
      if (!storedId && actual) {
        this.setSeason(actual.seasonId);
      }
    });
  }

  getSeasons(): Observable<Season[]> {
    const payload = {
      operationName: 'getSeasons',
      variables: {},
      query: `query getSeasons {
                getAllSeasons {
                  seasonId
                  name
                  shortName
                  isActual
                  sortValue
                }
              }
            `}
    return this.http.post<any>(
      'https://api.tvzofingen.ch/graphql',
      payload,
      {
        headers: {
          'Content-Type': 'application/json'
        }
      }
    ).pipe(
      map(result => result.data?.getAllSeasons ?? [])
    );
  }

  setSeason(season: number) {
    this.seasonSubject.next(season);
    localStorage.setItem('selectedSeason', season.toString());
  }

  getSeasonId() {
    return this.seasonSubject.value;
  }

  loadFromStorage() {
    const stored = localStorage.getItem('selectedSeason');
    if (stored) {
      const val = parseInt(stored);
      this.seasonSubject.next(val);
    }
  }

  getClubs(): Observable<Club[]> {
    if (this.clubsCache.length > 0) {
      return new Observable(observer => {
        observer.next(this.clubsCache);
        observer.complete();
      });
    } else {
      return new Observable(observer => {
        this.http.get<Club[]>(`${this.baseUrl}/clubs/`).subscribe(clubs => {
          const sortedClubs = clubs.sort((a: Club, b: Club) => a.clubName.localeCompare(b.clubName));
          this.clubsCache = sortedClubs;
          observer.next(sortedClubs);
          observer.complete();
        });
      });
    }
  }

  getVenues(): Observable<Venue[]> {
    if (this.clubsCache.length > 0) {
      return new Observable(observer => {
        observer.next(this.venuesCache);
        observer.complete();
      });
    } else {
      return new Observable(observer => {
        this.http.get<Venue[]>(
          `${this.baseUrl}/venues`,
          {
            headers: {
              'Content-Type': 'application/json'
            },
            withCredentials: false
          }
          ).subscribe(venues => {
          const sortedVenues = venues.sort((a: Venue, b: Venue) => a.venueName.localeCompare(b.venueName));
          this.venuesCache = sortedVenues;
          observer.next(sortedVenues);
          observer.complete();
        });
      });
    }
  }

  getGames(filters: { club?: number; venue?: number; season?: number }): Observable<Game[]> {
    const variables: any = {};
    variables.season_id = filters.season ?? 2025;
    if (filters.club) variables.club_id = filters.club;
    if (filters.venue) variables.venue_id = filters.venue;

    const payload = {
      operationName: 'getGames',
      variables: variables,
      query: `
      query getGames($club_id: Int, $team_id: Int, $venue_id: Int, $season_id: Int) {
        games(
          teamId: $team_id
          clubId: $club_id
          venueId: $venue_id
          seasonId: $season_id
        ) {
          gameNumber
          objectId
          objectType
          isLive
          seasonId
          gameDateTime
          homeTeamId
          homeTeamName
          homeTeamShortName
          homeTeamClubId
          homeTeamScore
          homeTeamScoreInterval
          awayTeamId
          awayTeamName
          awayTeamShortName
          awayTeamClubId
          awayTeamScore
          awayTeamScoreInterval
          venueName
          venueId
          type
          groupShortName
          leagueShortName
          gameStatusId
          gameStatus
          gameTypeId
          gameGroupOrCupId
          ltGameStatusId
          ltGameStatus
        }
      }
    `
    };

    return this.http.post<any>(
      'https://api.tvzofingen.ch/graphql',
      payload,
      {
        headers: {
          'Content-Type': 'application/json'
        }
      }
    ).pipe(
      map(result => result.data?.games ?? [])
    );
  }

  getGame(gameId: number): Observable<Game> {
    const payload = {
      operationName: 'getGame',
      variables: {
        game_id: +gameId,
        is_live: true
      },
      query: `query getGame($game_id: Int!, $is_live: Boolean) {
        game(gameId: $game_id, isLive: $is_live) {
          objectId
          objectType
          gameId
          gameNumber
          isLive
          seasonId
          gameDateTime
          homeTeamId
          homeTeamName
          homeTeamShortName
          homeTeamClubId
          homeTeamScore
          homeTeamScoreInterval
          awayTeamId
          awayTeamName
          awayTeamShortName
          awayTeamClubId
          awayTeamScore
          awayTeamScoreInterval
          venueId
          venueName
          gameStatusId
          gameStatus
          language
          spectators
          gameTypeGroupId
          gameInfoText
          gameGroupOrCupId
          ltGameTime
          ltGameStatusId
          ltGameStatus
          groupName
          groupShortName
          leagueName
          leagueShortName
          ref1Id
          ref1Name
          ref2Id
          ref2Name
          del1Id
          del1Name
          del2Id
          del2Name
          inspId
          inspName
          gameDuration
          ltCurrentGamePhaseText
          useReducedResultDisplay
          gameLeagueId
          __typename
        }
      }`
    }
    return this.http.post<any>(
      'https://api.tvzofingen.ch/graphql',
      payload,
      {
        headers: {
          'Content-Type': 'application/json'
        }
      }
    ).pipe(
      map(result => result.data?.game ?? null)
    );
  }

  getGamePlayerStats(gameId: number): Observable<GamePlayerStat[]> {
    const payload = {
      operationName: 'getGamePlayerStats',
      variables: {
        game_id: +gameId,
        is_live: true
      },
      query: `query getGamePlayerStats($game_id: Int, $is_live: Boolean) {
        getGamePlayerStats(gameId: $game_id, isLive: $is_live) {
          gameId
          teamId
          playerId
          teamName
          dressNr
          dressString
          playerName
          scoreAndShot
          scoreAndShot7m
          scorePercentage
          technicalErrors
          total2Minutes
          totalSuspension
          totalShots
          totalShots7m
          totalScore
          totalScore7m
          totalWarnings
          isHome
          function
          saveAndShot
          saveAndShot7m
          savePercentage
          totalShotsGK
          totalSaves
          totalShots7mGK
          totalSaves7m
          dataSource
          language
          __typename
        }
      }`
    };
    return this.http.post<any>(
      'https://api.tvzofingen.ch/graphql',
      payload,
      {
        headers: {
          'Content-Type': 'application/json'
        }
      }
    ).pipe(
      map(result => result.data?.getGamePlayerStats ?? [])
    );
  }
}
