import { Injectable } from '@angular/core';
import {
  HttpInterceptor, HttpRequest, HttpHandler, HttpErrorResponse
} from '@angular/common/http';
import { catchError, switchMap } from 'rxjs/operators';
import { throwError } from 'rxjs';
import {TokenAuthService} from "../services/token.service";
import {LoggerService} from '../services/logger.service';

@Injectable()
export class JwtInterceptor implements HttpInterceptor {
  constructor(private auth: TokenAuthService, private log: LoggerService) {}

  private readonly excludedHosts = [
    'api.tvzofingen.ch',
  ];

  private readonly excludedPaths = [
    '/public',
  ];

  private isExcluded(url: string): boolean {
    try {
      // 🧠 URL-Objekt erstellen (funktioniert auch mit relativen Pfaden)
      const parsedUrl = new URL(url, window.location.origin);
      const host = parsedUrl.host;
      const path = parsedUrl.pathname;

      // 🔍 Host-Ausschluss prüfen
      if (this.excludedHosts.some(h => host === h || host.endsWith(h))) {
        return true;
      }

      // 🔍 Pfad-Ausschluss prüfen
      if (this.excludedPaths.some(p => path.startsWith(p))) {
        return true;
      }

      return false;
    } catch (err) {
      // Wenn URL nicht parsebar (z. B. relative ohne Domain), prüfen wir nur Pfad:
      return this.excludedPaths.some(p => url.startsWith(p));
    }
  }

  intercept(req: HttpRequest<any>, next: HttpHandler) {
    if (this.isExcluded(req.url)) {
      return next.handle(req);
    }

    const token = this.auth.getAccessToken();
    let cloned = req;

    // 🔒 Access-Token anfügen
    if (token) {
      cloned = req.clone({
        setHeaders: { Authorization: `Bearer ${token}` }
      });
    }

    // 🧠 Fehler-Handling (401 → Refresh)
    return next.handle(cloned).pipe(
      catchError((err: HttpErrorResponse) => {
        this.log.log('in interceptor error handler');
        if (err.status === 401 && this.auth.getRefreshToken()) {
          return this.auth.refreshAccessToken().pipe(
            switchMap(newToken => {
              if (!newToken) return throwError(() => err);
              const retry = req.clone({
                setHeaders: { Authorization: `Bearer ${newToken}` }
              });
              return next.handle(retry);
            })
          );
        }
        return throwError(() => err);
      })
    );
  }
}
