import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, from, of } from 'rxjs';
import { tap, catchError } from 'rxjs/operators';
import {LoggerService} from './logger.service';
import {DateYMDPipe} from '../utils/date-ymd.pipe';
import {environment} from '../../environments/environment';

interface TokenPair {
  access_token: string;
  refresh_token: string;
}

@Injectable({ providedIn: 'root' })
export class TokenAuthService {
  private baseUrl = `${environment.apiHost}/api/auth`;
  private accessToken$ = new BehaviorSubject<string | null>(null);
  private refreshToken: string | null = null;
  private datePipe = new DateYMDPipe()

  pubAccessToken$ = new BehaviorSubject<string | null>(null);
  pubRefreshToken$ = new BehaviorSubject<string | null>(null);
  pubExpiration$ = new BehaviorSubject<string | null>(null);
  pubRefreshExpiration$ = new BehaviorSubject<string | null>(null);

  constructor(private http: HttpClient, private log: LoggerService) {
    this.restoreFromStorage();
    this.accessToken$.subscribe(accessToken => {
      this.pubAccessToken$.next(accessToken);
    })
    this.pubAccessToken$.subscribe(accessToken => {
      if (accessToken) {
        this.pubExpiration$.next(this.expiration(accessToken))
      } else {
        this.pubExpiration$.next('unknown');
      }
    })
    this.pubRefreshToken$.subscribe(refreshToken => {
      if (refreshToken) {
        this.pubRefreshExpiration$.next(this.expiration(refreshToken))
      } else {
        this.pubRefreshExpiration$.next('unknown');
      }
    })
  }

  private expiration(token: string):string {
    let date = new Date();
    try {
      const payload = JSON.parse(atob(token.split('.')[1]));
      date = new Date(payload.exp * 1000);
    } catch {
      this.log.error('Unable to parse token', token);
    }
    return this.datePipe.transformWithSeconds(date)
  }

  private isTokenExpired(token: string): boolean {
    try {
      const payload = JSON.parse(atob(token.split('.')[1]));
      const exp = payload.exp * 1000; // Sek. → ms
      return Date.now() > exp;
    } catch {
      this.log.error('Unable to parse token', token);
      return true;
    }
  }

  /** Beim App-Start Tokens aus localStorage lesen */
  private restoreFromStorage() {
    const access = localStorage.getItem('access_token');
    const refresh = localStorage.getItem('refresh_token');
    if (access) this.accessToken$.next(access);
    if (refresh) this.refreshToken = refresh;

    this.pubRefreshToken$.next(refresh);
  }

  /** Neues Token-Paar vom Server holen */
  initTokens() {
    const access = localStorage.getItem('access_token');
    const refresh = localStorage.getItem('refresh_token');

    // ✅ Wenn gültiges Token vorhanden → setze sie wieder
    if (access && refresh && !this.isTokenExpired(access)) {
      this.accessToken$.next(access);
      this.refreshToken = refresh;

      this.pubRefreshToken$.next(refresh);

      return of({ access_token: access, refresh_token: refresh });
    }

    // 🔁 Wenn Access abgelaufen, aber Refresh gültig → versuche Refresh
    if (refresh && !this.isTokenExpired(refresh)) {
      return this.http.post<{ access_token: string, refresh_token: string }>(
        `${this.baseUrl}/token/refresh/`,
        { refresh_token: refresh }
      ).pipe(
        tap(tokens => {
          this.saveTokens({
            access_token: tokens.access_token,
            refresh_token: tokens.refresh_token
          });
        }),
        catchError(err => {
          this.log.error('Refresh failed', err);
          throw err;
        })
      );
    }

    // 🆕 Wenn gar nichts vorhanden oder beides abgelaufen → neue Tokens
    return from(
      fetch(`${this.baseUrl}/token/issue`, {
        method: 'GET',
      }).then(async res => {
          if (!res.ok) throw new Error('Issue failed');
          const tokens = await res.json();
          this.saveTokens({
            access_token: tokens.access_token,
            refresh_token: tokens.refresh_token // Refresh bleibt gleich
          });
          return tokens;
        })
    )
  }

  /** Tokens im Speicher und lokal ablegen */
  private saveTokens(tokens: TokenPair) {
    localStorage.setItem('access_token', tokens.access_token);
    localStorage.setItem('refresh_token', tokens.refresh_token);
    this.accessToken$.next(tokens.access_token);
    this.refreshToken = tokens.refresh_token;

    this.pubRefreshToken$.next(tokens.refresh_token);
  }

  /** Access Token holen (für Interceptor) */
  getAccessToken() {
    return this.accessToken$.value;
  }

  /** Refresh Token holen */
  getRefreshToken() {
    return this.refreshToken;
  }

  /** Access Token manuell erneuern */
  refreshAccessToken() {
    if (!this.refreshToken) return of(null);

    return this.http.post<{ access_token: string, refresh_token: string }>(
      `${this.baseUrl}/token/refresh/`,
      { refresh_token: this.refreshToken }
    ).pipe(
      tap(tokens => {
        this.saveTokens({
          access_token: tokens.access_token,
          refresh_token: tokens.refresh_token
        });
      }),
      catchError(err => {
        if (err.status === 401) {
          // ⛔ Refresh abgelaufen → neue Tokens anfordern
          return this.http.get<{ access_token: string; refresh_token: string }>(
            `${this.baseUrl}/token/issue`
          ).pipe(
            tap(tokens => this.saveTokens(tokens)),
            tap(tokens => this.accessToken$.next(tokens.access_token)),
            catchError(issueErr => {
              this.log.error('Issue failed', issueErr);
              this.clearTokens();
              return of(null);
            })
          );
        }

        this.log.error('Refresh failed', err);
        this.clearTokens();
        return of(null);
      })
    );
  }

  /** Alles löschen */
  clearTokens() {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    this.accessToken$.next(null);
    this.refreshToken = null;

    this.pubRefreshToken$.next(null);
  }
}
