import { Component, Input, computed, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { marked } from 'marked';
import DOMPurify from 'dompurify';

@Component({
  selector: 'app-markdown-viewer',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="prose max-w-none dark:prose-invert" [innerHTML]="safeHtml()"></div>
  `
})
export class MarkdownViewerComponent {
  private _content = signal<string>('');

  @Input() set content(v: string | undefined) { this._content.set(v ?? ''); }

  safeHtml = computed(() => {
    const rawHtml = marked.parse(this._content());
    return DOMPurify.sanitize(rawHtml.toString());
  });
}
