import {inject, Injectable} from '@angular/core';
import {environment} from '../../environments/environment';
import {BehaviorSubject, firstValueFrom, Observable, throwError} from 'rxjs';
import {ToastService} from './toast.service';
import {Profile} from '../models/profile.model'
import {HttpClient} from '@angular/common/http';
import { catchError, map, tap} from 'rxjs/operators';
import {LoggerService} from './logger.service';

@Injectable({ providedIn: 'root' })
export class AuthService {
  private toast = inject(ToastService);
  private profile: Profile | undefined
  private baseUrl = `${environment.apiHost}/api`;
  private baseUrl_v1 = `${this.baseUrl}/v1.0`;

  constructor(private http: HttpClient, private log: LoggerService) {
    this.getProfile().then(profile => {
      if (profile) {
        this.profile = profile;
      }
    })
  }

  async getProfile(): Promise<Profile|undefined> {
    try {
      const response = await firstValueFrom(
        this.http.get<{ profile: any; errors?: any[] }>(
          `${this.baseUrl}/auth/profile`,
          { withCredentials: true }
        ).pipe(
          catchError(err => {
            // Netzwerk- oder Serverfehler
            this.toast.add('Netzwerkfehler', err.message || 'Unbekannter Fehler', 'error');
            throw err;
          })
        )
      );

      const { profile, errors } = response;

      if (errors?.length) {
        this.log.error(errors);
        this.toast.add(
          'Fehler bei GraphQL',
          errors[0].message || 'Unbekannter Fehler',
          'error'
        );
        return;
      }

      this.log.log(profile);
      return profile;

    } catch (err: any) {
      // Fängt alle nicht direkt abgefangenen Fehler ab
      this.toast.add('Netzwerkfehler', err.message || 'Unbekannter Fehler', 'error');
    }

    // Defaultwert zurückgeben (wie im Original)
    return {
      location_enabled: false,
      is_human: false,
      weight: { value: 0, max: 0 }
    };
  }

  getUserVotes(gameId: number): Observable<Map<number, number>> {
    return this.http
      .get<{ team: number; player: number }[]>(
        `${this.baseUrl_v1}/votes/${gameId}/`, {
        withCredentials: true,
        headers: { 'Content-Type': 'application/json' },
      })
      .pipe(
        map((data) => {
          const map = new Map<number, number>();
          data.forEach((row) => {
            map.set(row.team, row.player);
          });
          return map;
        }),
        catchError((err) => {
          this.log.error('❌ Fehler bei fetch der Votes', err);
          // Optional: falls du einen eigenen Toast-Service hast
          this.toast?.add?.(
            'Fehler bei fetch der Votes',
            err?.message || 'Unbekannter Fehler bei fetch der Votes',
            'error'
          );
          return throwError(() => err);
        })
      );
  }

  saveVote(gameId: number, teamId: number, playerId: number): Observable<any> {
    return this.http
      .post<{ data?: any; errors?: any[] }>(
        `${this.baseUrl_v1}/votes`,
        {
          game: gameId,
          team: teamId,
          player: playerId,
        },
        {
          withCredentials: true,
          headers: { 'Content-Type': 'application/json' },
        }
      )
      .pipe(
        tap((res) => {
          if (res.errors?.length) {
            this.log.error('GraphQL Fehler:', res.errors);
            this.toast.add(
              'Fehler bei GraphQL',
              res.errors[0].message || 'Unbekannter Fehler',
              'error'
            );
            throw new Error(res.errors[0].message);
          }
        }),
        catchError((err) => {
          this.log.error('Netzwerkfehler:', err);
          this.toast.add(
            'Netzwerkfehler',
            err?.message || 'Unbekannter Fehler beim POST',
            'error'
          );
          return throwError(() => err);
        })
      );
  }

  removeVote(gameId: number, teamId: number, playerId: number): Observable<any> {
    const body = { game: gameId, team: teamId, player: playerId };

    return this.http
      .request<void>('DELETE', `${this.baseUrl_v1}/votes`, {
        body, // DELETE unterstützt Body nur über request()
        withCredentials: true,
        headers: { 'Content-Type': 'application/json' },
      })
      .pipe(
        tap(() => {}),
        catchError((err) => {
          this.log.error('❌ Fehler beim Entfernen:', err);

          if (err.status >= 400) {
            this.toast.add('Fehler bei GraphQL', err.statusText || 'Unbekannter Fehler', 'error');
          } else {
            this.toast.add('Netzwerkfehler', err.message || 'Unbekannter Fehler', 'error');
          }
          return throwError(() => err);
        })
      );
  }
}
