//     provideHttpClient(withInterceptorsFromDi()),
//     { provide: HTTP_INTERCEPTORS, useClass: JwtInterceptor, multi: true },
//   ]
// }).catch(err => console.error(err));


async function main() {
  const container = document.createElement('div');
  document.body.appendChild(container);

  // 1️⃣ – Temporary Loading Component anzeigen (ohne inject())
  // Noch kein Injector vorhanden, wir nutzen später den von appRef
  let loadingInstance: any = null;
  let errorInstance: any = null;

  // App starten
  try {
    const appRef = await bootstrapApplication(AppComponent, {
      providers: [
        ...routingProviders,
        provideHttpClient(withInterceptorsFromDi()),
        { provide: HTTP_INTERCEPTORS, useClass: JwtInterceptor, multi: true },
      ],
    });

    const envInjector = appRef.injector.get(EnvironmentInjector);
    const auth = appRef.injector.get(TokenAuthService);

    // 🔄 LoadingComponent erstellen
    loadingInstance = createComponent(LoadingComponent, {
      environmentInjector: envInjector,
      hostElement: container
    });

    // 2️⃣ – Tokens initialisieren
    await firstValueFrom(auth.initTokens());

    console.log('destroy')
    // ✅ Tokens erfolgreich → Loading zerstören
    loadingInstance.destroy();
    container.remove();

  } catch (err: any) {
    console.error('❌ Fehler beim Initialisieren:', err);

    // 🔄 Loading entfernen
    loadingInstance?.destroy();
    container.remove();

    // ⚠️ ErrorComponent anzeigen
    const envInjector = (await bootstrapApplication(AppComponent)).injector.get(EnvironmentInjector);

    errorInstance = createComponent(ErrorComponent, {
      environmentInjector: envInjector,
      hostElement: container,
    });

    errorInstance.instance.message = err?.message ?? 'Token konnte nicht geladen werden.';
    errorInstance.changeDetectorRef.detectChanges();
  }
}

main().catch(console.error);
