import {Component, OnInit} from '@angular/core';
import {Router, RouterModule} from '@angular/router';
import {TvzApiService} from './services/tvz-api.service';
import {Season} from './models/season.model';
import {NavBarComponent} from './components/nav-bar/nav-bar.component';
import {ToastNotificationComponent} from './components/toast-notification/toast-notification.component';
import {AuthService} from './services/auth.service';

@Component({
  standalone: true,
  selector: 'app-root',
  imports: [RouterModule, NavBarComponent, ToastNotificationComponent],
  templateUrl: './app.component.html',
})
export class AppComponent implements OnInit {
  seasons: Season[] = [];

  constructor(private api: TvzApiService, private auth: AuthService, private router: Router) {}

  ngOnInit() {
    this.api.getSeasons().subscribe(seasons => {
      this.seasons = seasons;
    });
  }
}
